/* ================= Conversation (petites phrases, sujets, culture, expertise) ================= */
var PREP = null;
function prep() {
  if (PREP) return PREP;
  var g = function (a) { return a.map(function (k) { return toks(k); }).filter(function (x) { return x.length; }); };
  var lex = function (a) { var o = []; a.forEach(function (w) { norm(w).split(' ').forEach(function (x) { if (x) o.push(stem(x)); }); }); return o; };
  var byId = {};
  var tp = DATA.topics.map(function (t) { byId[t.id] = t; return { t: t, kw: g(t.kw) }; });
  PREP = { tp: tp, byId: byId, ex: DATA.expert.map(function (e) { return { e: e, kw: g(e.kw) }; }),
    qa: DATA.qa.map(function (q) { return { q: q, k: toks(q.k) }; }), kr: (DATA.kwr || []).map(function (x) { return { x: x, k: toks(x.k) }; }).filter(function (y) { return y.k.length; }), pos: lex(DATA.sent.pos), neg: lex(DATA.sent.neg) };
  return PREP;
}
function sideFact(text) {
  var n = N(text), T = toks(text), q, rr;
  if (!T.length || T.length > 10 || !(/\?/.test(text) || R(QCUE, n))) return null;
  q = findQA(T); if (q) return q.a;
  if (SK) { rr = retr().find(T); if (rr) return rr.qa ? rr.qa.a : rr.ex.a.split('//')[0].trim(); }
  return null;
}
var RETR = null;
function retr() {
  if (RETR || !SK) return RETR;
  var docs = [];
  prep().qa.forEach(function (x) { if (x.k.length) docs.push({ t: x.k, ref: { qa: x.q } }); });
  prep().ex.forEach(function (x) { x.kw.forEach(function (k) { docs.push({ t: k, ref: { ex: x.e } }); }); });
  RETR = SK.makeRetriever(docs);
  return RETR;
}
function allHit(T, arr) { for (var i = 0; i < arr.length; i++) if (!hit(T, arr[i])) return false; return true; }
function findTopic(T) {
  var best = null, bs = 0;
  prep().tp.forEach(function (x) { var s = 0; x.kw.forEach(function (k) { if (allHit(T, k)) s += k.length; }); if (s > bs) { bs = s; best = x.t; } });
  return best;
}
function findExpert(T) {
  var best = null, bs = 0;
  prep().ex.forEach(function (x) { x.kw.forEach(function (k) { if (allHit(T, k) && k.length > bs) { bs = k.length; best = x.e; } }); });
  return best;
}
function findQA(T) {
  var best = null, bs = 0;
  prep().qa.forEach(function (x) { if (x.k.length && allHit(T, x.k) && x.k.length > bs) { bs = x.k.length; best = x.q; } });
  return best;
}
function topicById(id) { return prep().byId[id] || null; }
function wordsOf(n) { return n ? n.split(' ').length : 0; }
function lcf(s) { return s ? s.charAt(0).toLowerCase() + s.slice(1) : s; }

/* phrases : jamais deux fois la même de suite pour une personne */
function pickIdx(c, key, len) {
  var u = (c.u = c.u || {}), l = (u[key] = u[key] || []), i, t = 0, lim = Math.min(len - 1, 40);
  do { i = Math.floor(rng() * len); t++; } while (l.indexOf(i) >= 0 && t < 12);
  l.push(i); while (l.length > lim) l.shift();
  return i;
}
function pickU(c, key, arr) { return arr && arr.length ? arr[pickIdx(c, key, arr.length)] : ''; }
function emit(s, c, x) {
  s = String(s).replace(/\{agence\}/g, agency()).replace(/\{nom\}/g, (c && c.known && c.known.nom) || '').replace(/\{x\}/g, x || '');
  return s.split('//').map(function (t) { return t.trim(); }).filter(function (t) { return t; });
}
function E(c, key, arr, x) { return emit(pickU(c, key, arr), c, x); }

/* ---- générateur de phrases : observations, astuces et questions composées sujet par sujet ---- */
function ucf(s) { return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; }
function okKid(c, id) { return !c.kid || DATA.kidOk.indexOf(id) >= 0; }
function okSw(c, id) { return okKid(c, id) && DATA.noSwitch.indexOf(id) < 0; }
function markTopic(c, id) {
  var r = (c.rt = c.rt || []), i = r.indexOf(id);
  if (i >= 0) r.splice(i, 1);
  r.push(id); while (r.length > 14) r.shift();
}
function pickTopic(c, from) {
  var r = (c.rt = c.rt || []), cand = [], X = prep();
  if (from) from.related.forEach(function (id) { if (r.indexOf(id) < 0 && okSw(c, id)) cand.push(id); });
  if (!cand.length) X.tp.forEach(function (x) { if (r.indexOf(x.t.id) < 0 && okSw(c, x.t.id)) cand.push(x.t.id); });
  if (!cand.length) { c.rt = []; X.tp.forEach(function (x) { if (okSw(c, x.t.id)) cand.push(x.t.id); }); }
  return topicById(cand[Math.floor(rng() * cand.length)]);
}
function genObs(c, t) {
  var g = t.gen, G = DATA.gen, subj, pred, tail, op, s;
  if (!g) return '';
  subj = pickU(c, 'gs:' + t.id, g.s); pred = pickU(c, 'gp:' + t.id, G.pred[g.k] || G.pred.neutral);
  tail = pickU(c, 'gt', G.tail); op = pickU(c, 'go', G.open);
  s = (op ? op + ' ' + subj : ucf(subj)) + ' ' + pred + tail + '.';
  return s.replace(/\bque (?=[aeiouyàâäéèêëîïôöùûü])/g, 'qu’');
}
